#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <cuda_pipeline.h>
constexpr int kThreads = 256;
constexpr int kRowsPerBlock = 8;
constexpr int kTileFloats = 1024;
constexpr int kTileVecs = kTileFloats / 4;
constexpr int kSplitK = 16;
__global__ void matvec_tiled_vec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long M,
    long K)
{
    __shared__ float4 sB[kTileVecs];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const long row = (long)blockIdx.x * kRowsPerBlock + warp;
    const bool active = row < M;
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
    float acc = 0.0f;
    const long num_tiles = K >> 10;
    for (long t = 0; t < num_tiles; ++t) {
        const long base_vec = t << 8;
        for (int i = threadIdx.x; i < kTileVecs; i += blockDim.x) {
            sB[i] = B4[base_vec + i];
        }
        __syncthreads();
        if (active) {
            const float4* __restrict__ A4 = reinterpret_cast<const float4*>(A + row * K);
            #pragma unroll 4
            for (int v = lane; v < kTileVecs; v += 32) {
                const float4 a = A4[base_vec + v];
                const float4 b = sB[v];
                acc += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            }
        }
        __syncthreads();
    }
    const unsigned int mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(mask, acc, offset);
    }
