// row. Each warp streams one row through a per-warp double buffer using
// cp.async, overlapping the next 128-float4 A tile with the current tile.
// The B operand is shared by every row in the block, so it is staged once
// per block in shared memory (also double-buffered through cp.async) instead
// of being re-fetched from global memory by each warp, cutting B traffic 8x.
// Four independent accumulators preserve memory-level parallelism, and the
// warp-shuffle reduction plus atomicAdd finalizes each K partition.
__global__ void matvec_splitk_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long M,
    long K,
    long k_chunk)
{
    constexpr int kStageVecs = 128;
    __shared__ float4 sA[2][kRowsPerBlock][kStageVecs];
    __shared__ float4 sB[2][kStageVecs];
