    const int warp = threadIdx.x >> 5;
    const long row = (long)blockIdx.x * kRowsPerBlock + warp;
    const bool active = row < M;
    const unsigned int mask = 0xffffffffu;
    const long k_begin = (long)blockIdx.y * k_chunk;
    const long nvec = k_chunk >> 2;
    const float4* __restrict__ A4 = reinterpret_cast<const float4*>(A + row * K + k_begin);
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B + k_begin);
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    float acc2 = 0.0f;
    float acc3 = 0.0f;
    const long num_stage_tiles = nvec / kStageVecs;
    if (num_stage_tiles > 0) {
        if (active) {
            for (int i = lane; i < kStageVecs; i += 32) {
                __pipeline_memcpy_async(&sA[0][warp][i], &A4[i], 16);
            }
        }
        if (threadIdx.x < kStageVecs) {
            __pipeline_memcpy_async(&sB[0][threadIdx.x], &B4[threadIdx.x], 16);
        }
        __pipeline_commit();
