            const int next = current ^ 1;
            if (t + 1 < num_stage_tiles) {
                const long next_vec = (t + 1) * kStageVecs;
                if (active) {
                    for (int i = lane; i < kStageVecs; i += 32) {
                        __pipeline_memcpy_async(&sA[next][warp][i], &A4[next_vec + i], 16);
                    }
                }
                if (threadIdx.x < kStageVecs) {
                    __pipeline_memcpy_async(&sB[next][threadIdx.x], &B4[next_vec + threadIdx.x], 16);
                }
                __pipeline_commit();
                __pipeline_wait_prior(1);
            } else {
                __pipeline_wait_prior(0);
