                const float4 a0 = sA[current][warp][lane];
                const float4 a1 = sA[current][warp][lane + 32];
                const float4 a2 = sA[current][warp][lane + 64];
                const float4 a3 = sA[current][warp][lane + 96];
                const float4 b0 = sB[current][lane];
                const float4 b1 = sB[current][lane + 32];
                const float4 b2 = sB[current][lane + 64];
                const float4 b3 = sB[current][lane + 96];
